using Microsoft.Data.Sqlite;
using MiniPharmacie.Business.Models;
using MiniPharmacie.Data.Database;

namespace MiniPharmacie.Business.Services;

public sealed class ReportingService(DatabaseInitializer db)
{
    public async Task<DashboardSnapshot> GetDashboardAsync(CancellationToken ct=default){await using var c=db.CreateConnection();await c.OpenAsync(ct);await using var q=c.CreateCommand();q.CommandText="SELECT COALESCE((SELECT SUM(TotalMinor) FROM Sales WHERE date(SoldAt)=date('now') AND Status='VALIDEE'),0),(SELECT COUNT(*) FROM Products p WHERE IsActive=1 AND COALESCE((SELECT SUM(QuantityOnHand) FROM Lots l WHERE l.ProductId=p.Id AND l.IsBlocked=0 AND (l.ExpiryDate IS NULL OR l.ExpiryDate>=date('now'))),0)=0),(SELECT COUNT(*) FROM Products p WHERE IsActive=1 AND COALESCE((SELECT SUM(QuantityOnHand) FROM Lots l WHERE l.ProductId=p.Id AND l.IsBlocked=0 AND (l.ExpiryDate IS NULL OR l.ExpiryDate>=date('now'))),0)>0 AND COALESCE((SELECT SUM(QuantityOnHand) FROM Lots l WHERE l.ProductId=p.Id AND l.IsBlocked=0 AND (l.ExpiryDate IS NULL OR l.ExpiryDate>=date('now'))),0)<=p.ReorderLevel),(SELECT COUNT(*) FROM Lots WHERE IsBlocked=0 AND ExpiryDate BETWEEN date('now') AND date('now','+'||COALESCE((SELECT Value FROM PharmacySettings WHERE Key='ExpiryAlertDays'),'90')||' days'))";await using var r=await q.ExecuteReaderAsync(ct);await r.ReadAsync(ct);return new(r.GetInt64(0),r.GetInt32(1),r.GetInt32(2),r.GetInt32(3));}
    public async Task<IReadOnlyList<ReportEntry>> GetSalesReportAsync(long userId,DateOnly from,DateOnly to,bool byPayment=false,CancellationToken ct=default){if(to<from)throw new ArgumentException("La période est invalide.");await using var c=db.CreateConnection();await c.OpenAsync(ct);var role=await UserRole(c,userId,ct);var manager=IsManager(role);await using var q=c.CreateCommand();var group=byPayment?"p.Method":"date(s.SoldAt)";q.CommandText=$"""SELECT {group},COALESCE(SUM(p.AmountMinor),0),COALESCE(SUM(CASE WHEN s.Status='VALIDEE' THEN p.AmountMinor ELSE 0 END),0),COALESCE((SELECT SUM(sr.RefundMinor) FROM SaleReversals sr JOIN Sales sx ON sx.Id=sr.SaleId WHERE date(sx.SoldAt) BETWEEN $from AND $to AND ($own=0 OR sx.UserId=$user)),0),COALESCE(SUM((SELECT SUM(c.Quantity*c.UnitCostMinor) FROM SaleLotConsumptions c JOIN SaleLines sl ON sl.Id=c.SaleLineId WHERE sl.SaleId=s.Id)),0) FROM Sales s JOIN Payments p ON p.SaleId=s.Id WHERE date(s.SoldAt) BETWEEN $from AND $to AND ($own=0 OR s.UserId=$user) AND COALESCE(p.ManualConfirmation,'') NOT LIKE 'Remboursement%' GROUP BY {group} ORDER BY {group}""";q.Parameters.AddWithValue("$from",from.ToString("yyyy-MM-dd"));q.Parameters.AddWithValue("$to",to.ToString("yyyy-MM-dd"));q.Parameters.AddWithValue("$own",manager?0:1);q.Parameters.AddWithValue("$user",userId);var rows=new List<ReportEntry>();await using var r=await q.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct)){var gross=r.GetInt64(1);var refunds=r.GetInt64(3);var cost=manager?r.GetInt64(4):0;rows.Add(new(r.GetString(0),0,gross,refunds,cost,manager?gross-refunds-cost:0));}return rows;}
    public async Task<IReadOnlyList<ReportEntry>> GetTopProductsAsync(long userId,DateOnly from,DateOnly to,int take=20,CancellationToken ct=default){await using var c=db.CreateConnection();await c.OpenAsync(ct);var role=await UserRole(c,userId,ct);var manager=IsManager(role);await using var q=c.CreateCommand();q.CommandText="SELECT sl.ProductName,SUM(sl.Quantity),SUM(sl.LineTotalMinor),COALESCE(SUM((SELECT SUM(rl.Quantity*sl.UnitPriceMinor) FROM SaleReturnLines rl WHERE rl.SaleLineId=sl.Id)),0),COALESCE(SUM((SELECT SUM(x.Quantity*x.UnitCostMinor) FROM SaleLotConsumptions x WHERE x.SaleLineId=sl.Id)),0) FROM SaleLines sl JOIN Sales s ON s.Id=sl.SaleId WHERE date(s.SoldAt) BETWEEN $from AND $to AND ($own=0 OR s.UserId=$user) AND s.Status<>'ANNULEE' GROUP BY sl.ProductName ORDER BY SUM(sl.Quantity) DESC LIMIT $take";q.Parameters.AddWithValue("$from",from.ToString("yyyy-MM-dd"));q.Parameters.AddWithValue("$to",to.ToString("yyyy-MM-dd"));q.Parameters.AddWithValue("$own",manager?0:1);q.Parameters.AddWithValue("$user",userId);q.Parameters.AddWithValue("$take",take);var rows=new List<ReportEntry>();await using var r=await q.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct)){var gross=r.GetInt64(2);var refund=r.GetInt64(3);var cost=manager?r.GetInt64(4):0;rows.Add(new(r.GetString(0),r.GetInt64(1),gross,refund,cost,manager?gross-refund-cost:0));}return rows;}
    public async Task<IReadOnlyList<ReportEntry>> GetStockReportAsync(long userId,CancellationToken ct=default){await RequireManager(userId,ct);await using var c=db.CreateConnection();await c.OpenAsync(ct);await using var q=c.CreateCommand();q.CommandText="SELECT p.Name,COALESCE(SUM(l.QuantityOnHand),0),0,0,COALESCE(SUM(l.QuantityOnHand*l.CostPriceMinor),0),0 FROM Products p LEFT JOIN Lots l ON l.ProductId=p.Id GROUP BY p.Id ORDER BY p.Name";var rows=new List<ReportEntry>();await using var r=await q.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))rows.Add(new(r.GetString(0),r.GetInt64(1),0,0,r.GetInt64(4),0));return rows;}
    public async Task<IReadOnlyList<ReportEntry>> GetLossesReportAsync(long userId,DateOnly from,DateOnly to,CancellationToken ct=default){await RequireManager(userId,ct);await using var c=db.CreateConnection();await c.OpenAsync(ct);await using var q=c.CreateCommand();q.CommandText="SELECT sm.MovementType||' — '||COALESCE(sm.Notes,''),SUM(ABS(sm.Quantity)),0,0,0,0 FROM StockMovements sm WHERE sm.MovementType IN ('AJUSTEMENT','ANNULATION') AND date(sm.OccurredAt) BETWEEN $from AND $to GROUP BY sm.MovementType,sm.Notes ORDER BY sm.MovementType";q.Parameters.AddWithValue("$from",from.ToString("yyyy-MM-dd"));q.Parameters.AddWithValue("$to",to.ToString("yyyy-MM-dd"));var rows=new List<ReportEntry>();await using var r=await q.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))rows.Add(new(r.GetString(0),r.GetInt64(1),0,0,0,0));return rows;}
    private static async Task<string?> UserRole(SqliteConnection c,long id,CancellationToken ct){await using var q=c.CreateCommand();q.CommandText="SELECT r.Name FROM Users u JOIN Roles r ON r.Id=u.RoleId WHERE u.Id=$u AND u.IsActive=1";q.Parameters.AddWithValue("$u",id);return (string?)await q.ExecuteScalarAsync(ct)??throw new UnauthorizedAccessException("Session utilisateur invalide.");}
    private async Task RequireManager(long id,CancellationToken ct){await using var c=db.CreateConnection();await c.OpenAsync(ct);if(!string.Equals(await UserRole(c,id,ct),"Responsable",StringComparison.OrdinalIgnoreCase))throw new UnauthorizedAccessException("Rapport réservé au responsable.");}
    private static bool IsManager(string? role)=>string.Equals(role,"Responsable",StringComparison.OrdinalIgnoreCase);
}
